public class CategoryPlot_removeRangeMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private CategoryDataset mockDataset;
    private CategoryAxis mockDomainAxis;
    private ValueAxis mockRangeAxis;

    @Before
    public void setUp() {
        mockDataset = Mockito.mock(CategoryDataset.class);
        mockDomainAxis = Mockito.mock(CategoryAxis.class);
        mockRangeAxis = Mockito.mock(ValueAxis.class);
        plot = new CategoryPlot(mockDataset, mockDomainAxis, mockRangeAxis, null);
        mockMarker = Mockito.mock(Marker.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Success() throws Exception {
        int index = 0;
        setupMarkers(Layer.FOREGROUND, index, mockMarker);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        verifyMarkerRemoved(Layer.FOREGROUND, index, mockMarker);
    }

    @Test
    public void testRemoveRangeMarker_Background_Success() throws Exception {
        int index = 0;
        setupMarkers(Layer.BACKGROUND, index, mockMarker);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Marker should be removed", result);
        verifyMarkerRemoved(Layer.BACKGROUND, index, mockMarker);
    }

    @Test
    public void testRemoveRangeMarker_MarkerNotFound() throws Exception {
        int index = 0;
        Marker differentMarker = Mockito.mock(Marker.class);
        setupMarkers(Layer.FOREGROUND, index, mockMarker);

        boolean result = plot.removeRangeMarker(index, differentMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not in list", result);
    }

    @Test
    public void testRemoveRangeMarker_NotifyFalse() throws Exception {
        int index = 0;
        setupMarkers(Layer.FOREGROUND, index, mockMarker);

        // notify = false
        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue(result);
        // We can't easily verify fireChangeEvent() without a spy or checking side effects, 
        // but we ensure the logic path is covered.
    }

    /**
     * Helper to inject markers into the private maps of CategoryPlot via reflection
     * since the provided API doesn't show a public way to add markers.
     */
    @SuppressWarnings("unchecked")
    private void setupMarkers(Layer layer, int index, Marker marker) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundRangeMarkers" : "backgroundRangeMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);

        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        ArrayList<Marker> list = new ArrayList<>();
        list.add(marker);
        map.put(index, list);
    }

    /**
     * Helper to verify the list content via reflection
     */
    @SuppressWarnings("unchecked")
    private void verifyMarkerRemoved(Layer layer, int index, Marker marker) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundRangeMarkers" : "backgroundRangeMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        ArrayList<Marker> list = map.get(index);
        assertFalse(list.contains(marker));
    }
}
